S = "shure-mxw"
# Microflex Wireless command strings (see the spec's sources): < GET ... >, < SET ... >, answered < REP ... >.
text(S, "get_device_id", {}, "< GET DEVICE_ID >", device_reply="< REP DEVICE_ID {Room-A                         } >", expect_result={'ok': {'kind': 'value', 'value': 'Room-A'}})
